import type { Question, QuestionOptionKey } from '../../types/questions'
import { reviewCapitaoAmadorQuestion } from './capitao-amador-review'

type QuestionSeed = {
  id: number
  topic: string
  statement: string
  options: [string, string, string, string, string]
  correct: QuestionOptionKey
  explanation: string
  conceptKey: string
  difficulty: Question['difficulty']
}

function buildQuestion(seed: QuestionSeed): Question {
  return {
    id: seed.id,
    subject: 'capitao-amador',
    topic: seed.topic,
    year: 2025,
    exam: 'Simulado Capitao Amador',
    source: 'Simulado',
    verified: true,
    statement: seed.statement,
    options: {
      A: seed.options[0],
      B: seed.options[1],
      C: seed.options[2],
      D: seed.options[3],
      E: seed.options[4],
    },
    correct: seed.correct,
    explanation: seed.explanation,
    conceptKey: seed.conceptKey,
    difficulty: seed.difficulty,
  }
}

const seeds: QuestionSeed[] = [
  { id: 20253001, topic: 'navegacao costeira / duas marcacoes', statement: 'Em navegacao costeira, duas marcacoes verdadeiras simultaneas de pontos notaveis diferentes permitem principalmente:', options: ['Determinar um ponto observado pela intersecao das linhas de posicao.', 'Calcular a altura da mare sem tabua.', 'Substituir a carta nautica em area restrita.', 'Medir a potencia real do motor.', 'Eliminar o desvio da agulha.'], correct: 'A', explanation: 'Cada marcacao gera uma linha de posicao. O cruzamento de duas linhas independentes fornece um ponto observado, que deve ser conferido com profundidades, perigos e coerencia da derrota.', conceptKey: 'cpa2.costeira.duas-marcacoes', difficulty: 'medium' },
  { id: 20253002, topic: 'navegacao costeira / triangulo de erro', statement: 'Quando tres marcacoes simultaneas formam um pequeno triangulo de erro na carta, o navegante deve:', options: ['Usar sempre o vertice mais proximo da costa.', 'Avaliar a qualidade das marcacoes e adotar uma posicao prudente dentro ou proxima ao triangulo.', 'Descartar a carta por estar obrigatoriamente incorreta.', 'Considerar apenas a marcacao numericamente maior.', 'Manter o rumo sem registrar a incerteza.'], correct: 'B', explanation: 'O triangulo de erro mostra imprecisoes de observacao, horario, carta ou instrumento. A decisao correta e avaliar o conjunto e escolher uma posicao conservadora em relacao aos perigos.', conceptKey: 'cpa2.costeira.triangulo-erro', difficulty: 'hard' },
  { id: 20253003, topic: 'navegacao costeira / marcacao de seguranca', statement: 'Uma marcacao de seguranca lancada na carta antes de passar por uma laje serve para:', options: ['Definir uma linha limite que a embarcacao nao deve cruzar.', 'Determinar o consumo horario de combustivel.', 'Calcular a variacao magnetica anual.', 'Escolher o canal VHF de chamada.', 'Medir a altura metacentrica.'], correct: 'A', explanation: 'A marcacao de seguranca funciona como uma linha de posicao limite. Se a marcacao observada indicar aproximacao do perigo, o comandante deve corrigir a derrota antes de entrar em area insegura.', conceptKey: 'cpa2.costeira.marcacao-seguranca', difficulty: 'hard' },
  { id: 20253004, topic: 'navegacao costeira / rumo verdadeiro e magnetico', statement: 'Para converter rumo verdadeiro em rumo magnetico, deve-se aplicar principalmente:', options: ['A altura da mare local.', 'O abatimento produzido pelo vento.', 'A variacao magnetica da regiao, com seu sinal correto.', 'A velocidade sobre o fundo.', 'A profundidade abaixo da quilha.'], correct: 'C', explanation: 'Rumo verdadeiro usa o norte verdadeiro; rumo magnetico usa o norte magnetico. A diferenca entre eles e a variacao magnetica local, que deve ser aplicada com atencao ao sinal leste ou oeste.', conceptKey: 'cpa2.costeira.rumo-verdadeiro-magnetico', difficulty: 'medium' },
  { id: 20253005, topic: 'navegacao costeira / desvio da agulha', statement: 'O desvio da agulha magnetica de bordo e melhor definido como:', options: ['Erro proprio da embarcacao, influenciado por massas e campos magneticos a bordo.', 'Valor fixo informado em todas as cartas nauticas.', 'Diferenca entre preamar e baixamar.', 'Erro causado apenas por corrente de mare.', 'Distancia entre dois waypoints consecutivos.'], correct: 'A', explanation: 'O desvio depende da instalacao e das influencias magneticas da propria embarcacao, podendo variar com o rumo. Por isso deve ser conhecido por tabela de desvios ou verificacoes praticas.', conceptKey: 'cpa2.costeira.desvio-agulha', difficulty: 'medium' },
  { id: 20253006, topic: 'navegacao costeira / abatimento', statement: 'Com vento forte pelo bordo, uma embarcacao pode apresentar abatimento, que significa:', options: ['Aumento automatico do calado.', 'Deslocamento lateral da derrota real em relacao ao rumo governado.', 'Reducao da variacao magnetica.', 'Perda de sinal AIS.', 'Aumento da borda livre.'], correct: 'B', explanation: 'O vento empurra a embarcacao para sotavento. Assim, a proa pode apontar para um rumo enquanto a derrota sobre o fundo se desloca lateralmente, exigindo correcao e controle de posicao.', conceptKey: 'cpa2.costeira.abatimento', difficulty: 'medium' },
  { id: 20253007, topic: 'navegacao costeira / corrente transversal', statement: 'Ao cruzar uma barra com corrente transversal significativa, a preocupacao principal deve ser:', options: ['Manter proa exatamente no rumo da carta sem compensacao.', 'Desligar o ecobatimetro para evitar alarmes.', 'Antecipar a deriva e manter margem para nao ser levado sobre perigos.', 'Usar apenas velocidade do motor para calcular posicao.', 'Ignorar boias se houver GPS.'], correct: 'C', explanation: 'Corrente transversal altera a derrota sobre o fundo. A embarcacao deve compensar o efeito, monitorar posicao e preservar margem lateral suficiente em relacao a bancos, pedras e margens.', conceptKey: 'cpa2.costeira.corrente-transversal', difficulty: 'hard' },
  { id: 20253008, topic: 'navegacao costeira / linha de sondagem', statement: 'A navegacao por linha de sondagem e util quando:', options: ['O fundo e uniforme e a carta nao tem profundidades.', 'As isobatas permitem comparar a profundidade medida com a posicao provavel na carta.', 'O GPS esta sempre com HDOP baixo.', 'Nao ha necessidade de considerar mare.', 'A visibilidade astronomica e excelente.'], correct: 'B', explanation: 'Comparar sondagens com isobatas pode confirmar a posicao, especialmente com costa baixa ou pouca referencia visual. A tecnica exige carta adequada e correcao de mare quando aplicavel.', conceptKey: 'cpa2.costeira.linha-sondagem', difficulty: 'medium' },
  { id: 20253009, topic: 'navegacao costeira / folga sob a quilha', statement: 'Antes de passar por area rasa, a folga sob a quilha deve considerar:', options: ['Somente a cor da agua.', 'Apenas a potencia do motor.', 'Profundidade da carta, altura da mare, calado, ondas e margem de seguranca.', 'Somente a distancia ao porto.', 'A quantidade de passageiros habilitados.'], correct: 'C', explanation: 'A profundidade disponivel no momento resulta da profundidade cartografada somada ou ajustada pela mare. Calado, movimento do mar e margem operacional definem se a passagem e segura.', conceptKey: 'cpa2.costeira.folga-quilha', difficulty: 'medium' },
  { id: 20253010, topic: 'navegacao costeira / escala da carta', statement: 'Para entrar em uma enseada com pedras e profundidades proximas, a carta mais indicada e normalmente:', options: ['A de menor escala, por mostrar area maior.', 'A carta meteorologica sinotica.', 'Qualquer carta que tenha rosa dos ventos.', 'A de maior escala disponivel para a area.', 'A mais antiga, por ter menos informacao.'], correct: 'D', explanation: 'Cartas de maior escala representam areas menores com mais detalhes. Sao preferiveis para aproximacao, canais, fundeio e navegacao em aguas restritas.', conceptKey: 'cpa2.costeira.escala-carta', difficulty: 'medium' },
  { id: 20253011, topic: 'navegacao costeira / avisos aos navegantes', statement: 'A consulta aos Avisos aos Navegantes antes da saida e importante porque:', options: ['Informa alteracoes de balizamento, perigos e restricoes que podem nao estar na carta a bordo.', 'Substitui a leitura da carta nautica.', 'Garante que toda boia estara iluminada.', 'Elimina a necessidade de vigia.', 'Serve apenas para navios mercantes.'], correct: 'A', explanation: 'Avisos atualizam cartas e publicacoes com mudancas temporarias ou permanentes. Navegar com informacao antiga pode levar a erro de balizamento, passagem por area restrita ou aproximacao de perigo.', conceptKey: 'cpa2.costeira.avisos-navegantes', difficulty: 'medium' },
  { id: 20253012, topic: 'navegacao costeira / derrota alternativa', statement: 'Marcar pontos de abrigo e derrotas alternativas no planejamento costeiro serve para:', options: ['Aumentar obrigatoriamente a distancia navegada.', 'Permitir decisao segura se tempo, visibilidade, combustivel ou tripulacao piorarem.', 'Dispensar previsao meteorologica.', 'Substituir todo controle de consumo.', 'Evitar o uso de carta de maior escala.'], correct: 'B', explanation: 'Planejamento robusto considera mudancas. Abrigos e alternativas reduzem a chance de insistir em uma derrota que deixou de ser segura por vento, mar, fadiga ou pane.', conceptKey: 'cpa2.costeira.derrota-alternativa', difficulty: 'medium' },
  { id: 20253013, topic: 'navegacao costeira / ponto estimado', statement: 'O ponto estimado e obtido principalmente por:', options: ['Tres marcacoes simultaneas de farois.', 'Pressao atmosferica e temperatura.', 'Rumo, velocidade e tempo desde uma posicao conhecida.', 'Codigo MMSI recebido pelo AIS.', 'Altura metacentrica transversal.'], correct: 'C', explanation: 'A estimativa propaga uma posicao conhecida usando rumo, velocidade e tempo. Como vento, corrente e governo imperfeito acumulam erro, deve ser conferida por observacoes.', conceptKey: 'cpa2.costeira.ponto-estimado', difficulty: 'medium' },
  { id: 20253014, topic: 'navegacao costeira / ponto corrido', statement: 'O ponto corrido pode ser usado quando o navegante:', options: ['Usa marcacoes do mesmo objeto em instantes diferentes, transportando uma linha de posicao pela derrota estimada.', 'Recebe posicao AIS de outro barco.', 'Calcula apenas a altura da mare.', 'Opera sem carta nautica.', 'Tem duas marcacoes simultaneas de objetos diferentes.'], correct: 'A', explanation: 'No ponto corrido, uma linha de posicao anterior e avancada conforme o deslocamento estimado da embarcacao. O cruzamento com nova linha ajuda a determinar a posicao.', conceptKey: 'cpa2.costeira.ponto-corrido', difficulty: 'hard' },
  { id: 20253015, topic: 'navegacao costeira / alinhamento', statement: 'Quando dois pontos notaveis em terra aparecem alinhados, essa observacao fornece:', options: ['A velocidade da corrente.', 'Uma linha de posicao definida pelo alinhamento.', 'O desvio da agulha para todos os rumos.', 'A profundidade exata sob a quilha.', 'O horario da proxima preamar.'], correct: 'B', explanation: 'Alinhamentos sao referencias visuais precisas. Enquanto os objetos permanecem alinhados, a embarcacao esta sobre a linha correspondente, util para confirmar passagem segura.', conceptKey: 'cpa2.costeira.alinhamento', difficulty: 'medium' },
  { id: 20253016, topic: 'navegacao costeira / setor de farol', statement: 'Um farol com setores coloridos auxilia porque:', options: ['A cor observada indica o setor angular em que a embarcacao se encontra.', 'A cor substitui a carta nautica.', 'O setor vermelho sempre indica agua profunda.', 'O setor branco sempre proibe navegacao.', 'A cor calcula autonomia.'], correct: 'A', explanation: 'Setores luminosos delimitam areas. A cor observada deve ser comparada com a carta para confirmar setor seguro ou aproximacao de perigo.', conceptKey: 'cpa2.costeira.setor-farol', difficulty: 'medium' },
  { id: 20253017, topic: 'navegacao costeira / sistema IALA B', statement: 'Ao entrar em porto brasileiro vindo do mar pelo canal balizado, no sistema lateral IALA B:', options: ['As marcas verdes ficam a boreste.', 'As marcas encarnadas ficam a boreste e as verdes a bombordo.', 'As marcas cardinais substituem as laterais.', 'As cores nao dependem do sentido convencional.', 'As marcas laterais indicam apenas fundeadouros.'], correct: 'B', explanation: 'O Brasil usa a regiao B. No sentido convencional vindo do mar para o porto, encarnado fica a boreste e verde a bombordo. Inverter isso pode tirar a embarcacao do canal.', conceptKey: 'cpa2.costeira.iala-b', difficulty: 'medium' },
  { id: 20253018, topic: 'navegacao costeira / marca cardinal norte', statement: 'Uma marca cardinal norte indica que as aguas mais seguras estao:', options: ['Ao sul da marca.', 'Ao norte da marca.', 'Sempre no centro da marca.', 'A oeste da marca.', 'Em qualquer lado, se houver GPS.'], correct: 'B', explanation: 'Marcas cardinais indicam o quadrante seguro em relacao ao perigo. Uma cardinal norte informa que a embarcacao deve passar ao norte da marca.', conceptKey: 'cpa2.costeira.cardinal-norte', difficulty: 'medium' },
  { id: 20253019, topic: 'navegacao costeira / perigo isolado', statement: 'Uma marca de perigo isolado sinaliza:', options: ['Perigo limitado com aguas navegaveis ao redor conforme a carta.', 'Canal preferencial de entrada.', 'Area sempre proibida em grande raio.', 'Boia de bombordo fora de posicao.', 'Local recomendado para fundeio.'], correct: 'A', explanation: 'A marca fica sobre ou junto de perigo de pequena extensao. O navegante nao deve passar sobre ela, embora possa haver agua segura ao redor dependendo da carta.', conceptKey: 'cpa2.costeira.perigo-isolado', difficulty: 'medium' },
  { id: 20253020, topic: 'navegacao costeira / escolha de fundeio', statement: 'Antes de fundear em uma enseada, a escolha do ponto deve considerar:', options: ['Apenas proximidade da praia.', 'Somente a direcao da proa ao chegar.', 'Tipo de fundo, profundidade, raio de giro, abrigo, trafego e restricoes.', 'A cor da amarra.', 'Sinal de internet no local.'], correct: 'C', explanation: 'Fundeio seguro depende de teneca do fundo, profundidade compativel, espaco para giro e protecao. Tambem e preciso evitar canais, cabos, dutos e areas proibidas.', conceptKey: 'cpa2.costeira.fundeio', difficulty: 'medium' },
  { id: 20253021, topic: 'navegacao costeira / raio de giro', statement: 'O raio de giro de uma embarcacao fundeada deve ser previsto para evitar:', options: ['Colisao, encalhe ou entrada em area restrita quando vento ou corrente mudarem.', 'Variacao magnetica.', 'Perda de sinal AIS por alcance.', 'Aumento de temperatura do motor.', 'Erro de horario legal.'], correct: 'A', explanation: 'A embarcacao gira em torno da ancora conforme vento e corrente. O comandante deve garantir espaco livre em todo o circulo provavel, nao apenas na posicao inicial.', conceptKey: 'cpa2.costeira.raio-giro', difficulty: 'medium' },
  { id: 20253022, topic: 'navegacao costeira / entrada noturna', statement: 'Em entrada noturna por canal estreito, a conduta prudente e:', options: ['Entrar em alta velocidade para reduzir exposicao.', 'Confiar apenas na trilha antiga do GPS.', 'Apagar luzes de navegacao para enxergar melhor.', 'Reduzir velocidade, identificar luzes, conferir carta e manter vigia reforcada.', 'Ignorar profundidade se o canal tiver boias.'], correct: 'D', explanation: 'A noite reduz referencias e aumenta risco de confusao de luzes. Velocidade controlada, conferencia cruzada e vigia reforcada permitem reagir antes que um erro se torne critico.', conceptKey: 'cpa2.costeira.entrada-noturna', difficulty: 'hard' },
  { id: 20253023, topic: 'navegacao costeira / nevoeiro', statement: 'Ao ser surpreendido por nevoeiro costeiro, o capitao-amador deve:', options: ['Aumentar velocidade para sair logo da area.', 'Reduzir velocidade, emitir sinais adequados, reforcar vigia e controlar posicao.', 'Desligar equipamentos sonoros.', 'Aproximar-se da arrebentacao para obter referencias.', 'Navegar apenas por memoria.'], correct: 'B', explanation: 'Nevoeiro reduz deteccao de perigos e trafego. A resposta correta combina velocidade segura, sinais sonoros, vigia, radar/AIS se disponiveis e controle rigoroso da posicao.', conceptKey: 'cpa2.costeira.nevoeiro', difficulty: 'hard' },
  { id: 20253024, topic: 'navegacao costeira / velocidade em aguas restritas', statement: 'Em aguas restritas, velocidade segura deve considerar:', options: ['Apenas a velocidade maxima do fabricante.', 'Distancia de parada, manobrabilidade, trafego, profundidade, visibilidade e efeitos de margem.', 'Somente corrente favoravel.', 'A cor das boias.', 'A quantidade de waypoints.'], correct: 'B', explanation: 'Velocidade segura e aquela que permite agir a tempo. Em canais, pouca profundidade, trafego, squat e efeitos de margem tornam velocidade excessiva especialmente perigosa.', conceptKey: 'cpa2.costeira.velocidade-restrita', difficulty: 'medium' },
  { id: 20253025, topic: 'navegacao costeira / squat', statement: 'O efeito squat pode causar:', options: ['Aumento aparente do calado dinamico e reducao da folga sob a quilha.', 'Correcao automatica do abatimento.', 'Aumento da borda livre.', 'Eliminacao da corrente.', 'Melhora da estabilidade por principio.'], correct: 'A', explanation: 'Em aguas rasas ou canais, o escoamento ao redor do casco pode fazer a embarcacao afundar e alterar trim. O risco cresce com a velocidade.', conceptKey: 'cpa2.costeira.squat', difficulty: 'hard' },
  { id: 20253026, topic: 'navegacao costeira / interpolacao de mare', statement: 'Se a passagem por um baixio ocorre entre preamar e baixamar, o navegante deve:', options: ['Usar sempre a profundidade da carta sem ajuste.', 'Somar o calado a profundidade.', 'Estimar a altura da mare no horario de passagem por metodo adequado.', 'Considerar mare nula.', 'Aplicar apenas o desvio da agulha.'], correct: 'C', explanation: 'A altura da mare varia continuamente. Para obter profundidade disponivel no horario real, deve-se estimar a mare e combinar com profundidade de carta e calado.', conceptKey: 'cpa2.costeira.interpolacao-mare', difficulty: 'hard' },
  { id: 20253027, topic: 'navegacao costeira / derrota sobre o fundo', statement: 'A derrota sobre o fundo difere do rumo de proa quando:', options: ['Ha vento ou corrente deslocando a embarcacao durante o movimento.', 'A carta e de grande escala.', 'A bussola esta compensada.', 'O mar esta absolutamente calmo.', 'O motor opera em rotacao constante.'], correct: 'A', explanation: 'Rumo de proa e para onde a embarcacao aponta; derrota sobre o fundo e o caminho efetivo. Vento e corrente podem criar diferenca significativa entre os dois.', conceptKey: 'cpa2.costeira.derrota-fundo', difficulty: 'medium' },
  { id: 20253028, topic: 'navegacao costeira / alcance geografico', statement: 'A distancia em que um farol pode ser avistado depende principalmente:', options: ['Da cor do casco.', 'Do numero de satelites GPS.', 'Do canal VHF selecionado.', 'Da altura do foco, altura do observador e visibilidade atmosferica.', 'Da temperatura do motor.'], correct: 'D', explanation: 'A curvatura da Terra limita o alcance geografico. Alturas maiores aumentam a distancia teorica, mas nevoeiro, chuva e bruma podem reduzir o alcance real.', conceptKey: 'cpa2.costeira.alcance-geografico', difficulty: 'medium' },
  { id: 20253029, topic: 'navegacao costeira / caracteristica luminosa', statement: 'Para identificar uma luz de auxilio a navegacao, deve-se comparar principalmente:', options: ['Caracteristica, periodo, cor, setor e alcance informado.', 'Apenas a intensidade subjetiva.', 'Somente a direcao do vento.', 'A marca do equipamento luminoso.', 'A velocidade do motor.'], correct: 'A', explanation: 'Farois e boias luminosas sao identificados por ritmo, periodo, cor, setor e alcance. A comparacao evita confundir luzes proximas ou luzes de terra.', conceptKey: 'cpa2.costeira.caracteristica-luminosa', difficulty: 'medium' },
  { id: 20253030, topic: 'navegacao costeira / area restrita', statement: 'Uma area proibida ou restrita indicada na carta deve ser tratada como:', options: ['Informacao decorativa.', 'Area sempre liberada para lazer.', 'Limite operacional que exige respeito as instrucoes da carta, avisos e autoridade.', 'Local preferencial de fundeio.', 'Trecho sem necessidade de vigia.'], correct: 'C', explanation: 'Cartas indicam areas militares, ambientais, cabos, dutos, fundeadouros e zonas especiais. Ignorar restricoes pode gerar risco operacional e infracao.', conceptKey: 'cpa2.costeira.area-restrita', difficulty: 'medium' },
  { id: 20253031, topic: 'navegacao costeira / cabo submarino', statement: 'Ao planejar fundeio perto de area indicada como cabo submarino, a atitude correta e:', options: ['Fundear sobre o cabo para melhor teneca.', 'Evitar fundeio sobre ou proximo ao cabo, respeitando a carta.', 'Usar amarra maior e ignorar a restricao.', 'Desconsiderar se a profundidade for grande.', 'Aumentar velocidade durante o fundeio.'], correct: 'B', explanation: 'Ancora e amarra podem danificar cabos e dutos. A simbologia da carta existe para orientar afastamento e evitar risco, prejuizo e responsabilidade.', conceptKey: 'cpa2.costeira.cabo-submarino', difficulty: 'medium' },
  { id: 20253032, topic: 'navegacao costeira / intervalo de controle', statement: 'O intervalo entre controles de posicao deve ser menor quando:', options: ['A embarcacao navega perto de perigos, em baixa visibilidade ou sob corrente significativa.', 'A carta possui muitas cores.', 'O destino esta longe.', 'O motor opera em baixa rotacao.', 'A tripulacao conhece o porto.'], correct: 'A', explanation: 'Quanto menor a margem para erro, mais frequente deve ser a verificacao. Perigos proximos, corrente e visibilidade ruim exigem controle em intervalos curtos.', conceptKey: 'cpa2.costeira.intervalo-controle', difficulty: 'medium' },
  { id: 20253033, topic: 'navegacao costeira / waypoint seguro', statement: 'Um waypoint costeiro deve ser posicionado:', options: ['Exatamente sobre uma pedra para facilitar referencia.', 'Sempre no centro de uma ilha.', 'Sem relacao com profundidade.', 'Em local que mantenha margem de seguranca contra perigos e erro de chegada.', 'Apenas onde o GPS sugerir automaticamente.'], correct: 'D', explanation: 'Waypoints nao devem ficar sobre perigos nem tao proximos deles que erro de GPS, raio de chegada ou atraso de manobra coloque a embarcacao em risco.', conceptKey: 'cpa2.costeira.waypoint-seguro', difficulty: 'hard' },
  { id: 20253034, topic: 'navegacao costeira / margem de erro', statement: 'Ao passar proximo a uma laje submersa, a margem de erro deve considerar:', options: ['Precisao da posicao, escala da carta, governo, corrente, visibilidade e tempo de reacao.', 'Somente a quantidade de cartas a bordo.', 'A cor do fundo no ecobatimetro.', 'A potencia do som.', 'A distancia ate o porto.'], correct: 'A', explanation: 'Mesmo com GPS ha erro de carta, datum, operador, governo e ambiente. Por isso uma derrota segura nao deve passar rente a perigo.', conceptKey: 'cpa2.costeira.margem-erro', difficulty: 'hard' },
  { id: 20253035, topic: 'navegacao costeira / datum', statement: 'Se o datum do GPS for diferente do datum da carta, pode ocorrer:', options: ['Aumento real da profundidade.', 'Deslocamento aparente da posicao plotada em relacao aos perigos da carta.', 'Eliminacao do erro de governo.', 'Mudanca fisica da variacao magnetica.', 'Bloqueio das boias na tela.'], correct: 'B', explanation: 'Datum e o referencial das coordenadas. Diferencas entre datum do equipamento e da carta podem deslocar a posicao exibida, o que e critico em aguas restritas.', conceptKey: 'cpa2.costeira.datum', difficulty: 'hard' },
  { id: 20253036, topic: 'navegacao costeira / rumo de resguardo', statement: 'Um rumo de resguardo e planejado para:', options: ['Aproximar a derrota da costa.', 'Economizar cartas nauticas.', 'Manter a embarcacao afastada de perigo mesmo com pequenos erros ou corrente.', 'Aumentar velocidade media.', 'Substituir luzes de navegacao.'], correct: 'C', explanation: 'O rumo de resguardo incorpora margem para incertezas. Ele evita que pequenos erros de governo, vento ou corrente levem a embarcacao para uma area perigosa.', conceptKey: 'cpa2.costeira.rumo-resguardo', difficulty: 'medium' },
  { id: 20253037, topic: 'navegacao costeira / eta e corrente', statement: 'Se uma corrente contraria reduz a velocidade sobre o fundo, um ETA calculado apenas pela velocidade na agua ficara:', options: ['Adiantado em relacao a chegada real provavel.', 'Atrasado em relacao a chegada real provavel.', 'Sempre correto.', 'Igual ao horario de preamar.', 'Dependente apenas da variacao magnetica.'], correct: 'A', explanation: 'ETA depende da velocidade sobre o fundo. Com corrente contraria, a embarcacao cobre menos distancia por hora; ignorar isso faz prever chegada cedo demais.', conceptKey: 'cpa2.costeira.eta-corrente', difficulty: 'medium' },
  { id: 20253038, topic: 'navegacao costeira / recalada', statement: 'Na recalada em costa pouco conhecida, a primeira identificacao positiva de um auxilio deve ser usada para:', options: ['Aumentar imediatamente a velocidade.', 'Dispensar todas as demais verificacoes.', 'Confirmar posicao aproximada e reduzir incertezas antes de seguir para aguas restritas.', 'Corrigir a estabilidade.', 'Escolher canal de lazer.'], correct: 'C', explanation: 'Recalada e fase critica. Identificar corretamente um farol, boia ou ponto notavel reduz incerteza, mas ainda deve ser cruzado com carta, profundidade e instrumentos.', conceptKey: 'cpa2.costeira.recalada', difficulty: 'medium' },
  { id: 20253039, topic: 'navegacao costeira / resguardo da costa', statement: 'Ao navegar paralelo a costa com perigos isolados, uma boa pratica e:', options: ['Aproximar-se da arrebentacao para encurtar caminho.', 'Usar apenas a bussola sem conferir posicao.', 'Navegar sobre a isobata mais rasa.', 'Manter sempre a mesma velocidade.', 'Definir distancia minima de resguardo e controlar se ela esta sendo respeitada.'], correct: 'E', explanation: 'Distancia de resguardo transforma seguranca em criterio operacional. Ela deve considerar perigos, profundidade, corrente, vento, visibilidade e capacidade de manobra.', conceptKey: 'cpa2.costeira.resguardo-costa', difficulty: 'medium' },
  { id: 20253040, topic: 'navegacao costeira / verificacao cruzada', statement: 'A verificacao cruzada entre carta, GPS, ecobatimetro, radar e observacao visual e importante porque:', options: ['Nenhum meio isolado e infalivel, e a comparacao reduz erro nao percebido.', 'Todos mostram sempre a mesma informacao.', 'A carta perde validade quando ha GPS.', 'O ecobatimetro indica rumo verdadeiro.', 'A observacao visual substitui planejamento.'], correct: 'A', explanation: 'Divergencias entre meios podem revelar erro de datum, escala, identificacao, profundidade, atualizacao ou sensor. A redundancia melhora a decisao do comandante.', conceptKey: 'cpa2.costeira.verificacao-cruzada', difficulty: 'hard' },
  { id: 20253041, topic: 'navegacao eletronica / gps trilateracao', statement: 'O GPS determina a posicao da embarcacao principalmente por:', options: ['Sinais de satelites e tempo de propagacao recebido pelo receptor.', 'Correntes maritimas medidas pela carta.', 'Sinais luminosos de farois costeiros.', 'Pressao atmosferica local.', 'Velocidade do motor.'], correct: 'A', explanation: 'O receptor calcula distancias aos satelites a partir do tempo de chegada dos sinais. Com varios satelites, resolve a posicao por trilateracao.', conceptKey: 'cpa2.eletronica.gps-trilateracao', difficulty: 'medium' },
  { id: 20253042, topic: 'navegacao eletronica / hdop', statement: 'Um valor alto de HDOP no GPS indica:', options: ['Maior profundidade sob a quilha.', 'Geometria desfavoravel dos satelites e menor confiabilidade horizontal.', 'Garantia de precisao maxima.', 'Falha obrigatoria do radar.', 'Aumento da potencia VHF.'], correct: 'B', explanation: 'HDOP expressa a qualidade geometrica dos satelites para posicao horizontal. Quanto maior, maior tende a ser a incerteza da posicao.', conceptKey: 'cpa2.eletronica.hdop', difficulty: 'hard' },
  { id: 20253043, topic: 'navegacao eletronica / perda de gps', statement: 'Se o GPS perder sinal durante navegacao costeira, a acao correta e:', options: ['Seguir sem controle ate o sinal voltar.', 'Aumentar velocidade.', 'Marcar o ultimo ponto confiavel e continuar por estimativa e referencias disponiveis.', 'Apagar a carta.', 'Confiar na posicao congelada indefinidamente.'], correct: 'C', explanation: 'A ultima posicao confiavel deve ser registrada. A partir dela, usa-se rumo, velocidade, tempo, profundidade, radar e referencias visuais ate recuperar posicao confiavel.', conceptKey: 'cpa2.eletronica.perda-gps', difficulty: 'medium' },
  { id: 20253044, topic: 'navegacao eletronica / zoom do chartplotter', statement: 'No chartplotter, zoom excessivo pode ser perigoso porque:', options: ['Cria detalhe cartografico real.', 'Aumenta a profundidade.', 'Corrige o datum.', 'Pode dar falsa sensacao de precisao maior que a carta possui.', 'Impede recepcao AIS.'], correct: 'D', explanation: 'Zoom nao melhora a qualidade da carta base. Em escala inadequada, a tela pode parecer precisa enquanto a informacao nautica real continua limitada.', conceptKey: 'cpa2.eletronica.zoom-chartplotter', difficulty: 'hard' },
  { id: 20253045, topic: 'navegacao eletronica / alarme de chegada', statement: 'O raio do alarme de chegada a waypoint deve considerar:', options: ['Apenas o volume do alarme.', 'A velocidade, o local e o tempo necessario para manobra antes do ponto.', 'A cor da trilha.', 'A profundidade maxima da carta.', 'O comprimento da antena VHF.'], correct: 'B', explanation: 'Um raio pequeno pode alertar tarde; um raio grande pode confundir. O ajuste deve dar tempo para confirmar a proxima perna e manobrar com seguranca.', conceptKey: 'cpa2.eletronica.alarme-chegada', difficulty: 'medium' },
  { id: 20253046, topic: 'navegacao eletronica / xte', statement: 'O XTE exibido em GPS ou chartplotter representa:', options: ['Erro lateral em relacao a derrota planejada.', 'Profundidade sob a quilha.', 'Pressao reduzida ao nivel do mar.', 'Variacao magnetica.', 'Distancia vertical ao satelite.'], correct: 'A', explanation: 'Cross Track Error e a distancia lateral entre a posicao atual e a linha planejada. Ajuda a corrigir a derrota sem depender apenas da proa.', conceptKey: 'cpa2.eletronica.xte', difficulty: 'medium' },
  { id: 20253047, topic: 'navegacao eletronica / cog sog', statement: 'COG e SOG significam, respectivamente:', options: ['Calado operacional e sondagem geral.', 'Codigo operacional e sinal de governo.', 'Rumo sobre o fundo e velocidade sobre o fundo.', 'Centro de gravidade e superficie livre.', 'Canal oficial e chamada seletiva.'], correct: 'C', explanation: 'COG e a direcao real do movimento sobre o fundo; SOG e a velocidade sobre o fundo. Ambos podem diferir da proa e da velocidade na agua por vento e corrente.', conceptKey: 'cpa2.eletronica.cog-sog', difficulty: 'medium' },
  { id: 20253048, topic: 'navegacao eletronica / ais classe b', statement: 'O AIS Classe B em embarcacoes de esporte e recreio serve principalmente para:', options: ['Substituir vigia visual.', 'Transmitir e receber dados de identificacao, posicao, rumo e velocidade.', 'Garantir prioridade de passagem.', 'Medir profundidade.', 'Bloquear chamadas VHF.'], correct: 'B', explanation: 'AIS melhora a consciencia situacional, mas nao substitui vigia, RIPEAM, radar ou julgamento. Nem toda embarcacao transmite AIS.', conceptKey: 'cpa2.eletronica.ais-classe-b', difficulty: 'medium' },
  { id: 20253049, topic: 'navegacao eletronica / cpa tcpa', statement: 'Em AIS ou ARPA, CPA e TCPA indicam:', options: ['Profundidade minima e hora da mare.', 'Potencia e canal.', 'Altura de antena e alcance.', 'Distancia minima prevista de aproximacao e tempo ate ela.', 'Consumo e autonomia.'], correct: 'D', explanation: 'CPA mostra quao perto os alvos devem passar; TCPA mostra quando isso ocorrera. Valores pequenos exigem avaliacao e manobra antecipadas.', conceptKey: 'cpa2.eletronica.cpa-tcpa', difficulty: 'hard' },
  { id: 20253050, topic: 'navegacao eletronica / limitacao ais', statement: 'Uma limitacao importante do AIS e:', options: ['Mostrar todos os troncos, pedras e boias apagadas.', 'Substituir radar em chuva forte.', 'Depender de outras embarcacoes transmitirem dados corretos.', 'Calcular estabilidade transversal.', 'Ser infalivel em embarcacoes pequenas.'], correct: 'C', explanation: 'AIS e colaborativo. So aparecem alvos equipados e transmitindo corretamente; objetos, embarcacoes sem AIS e dados errados podem nao ser percebidos.', conceptKey: 'cpa2.eletronica.limitacao-ais', difficulty: 'medium' },
  { id: 20253051, topic: 'navegacao eletronica / radar ganho', statement: 'No radar, ganho excessivamente alto tende a:', options: ['Saturar a tela com ruido e dificultar ecos reais.', 'Eliminar clutter de mar automaticamente.', 'Aumentar o alcance fisico da antena.', 'Corrigir a proa.', 'Reduzir area cega a zero.'], correct: 'A', explanation: 'Ganho alto demais amplifica ruido junto com ecos. O ajuste correto busca mostrar alvos uteis sem mascarar contatos fracos ou criar excesso de informacao.', conceptKey: 'cpa2.eletronica.radar-ganho', difficulty: 'medium' },
  { id: 20253052, topic: 'navegacao eletronica / sea clutter', statement: 'O controle sea clutter do radar serve para:', options: ['Alterar o datum do GPS.', 'Reduzir ecos proximos causados por ondas e retorno do mar.', 'Transmitir mensagem DSC.', 'Medir calado.', 'Aumentar volume de alarme.'], correct: 'B', explanation: 'Sea clutter atenua retornos do mar, principalmente proximos. Se usado em excesso, tambem pode apagar alvos pequenos, exigindo regulagem cuidadosa.', conceptKey: 'cpa2.eletronica.sea-clutter', difficulty: 'medium' },
  { id: 20253053, topic: 'navegacao eletronica / rain clutter', statement: 'Em chuva forte, o controle rain clutter ajuda a:', options: ['Atenuar ecos de precipitacao que podem mascarar alvos.', 'Medir salinidade.', 'Dispensar reducao de velocidade.', 'Aumentar potencia AIS.', 'Corrigir variacao magnetica.'], correct: 'A', explanation: 'Precipitacao pode criar uma massa de ecos na tela. O filtro melhora a leitura, mas seu excesso pode reduzir ecos fracos de alvos reais.', conceptKey: 'cpa2.eletronica.rain-clutter', difficulty: 'medium' },
  { id: 20253054, topic: 'navegacao eletronica / radar para posicao', statement: 'Uma utilidade do radar em navegacao costeira e:', options: ['Receber previsao meteorologica oficial.', 'Medir salinidade.', 'Medir distancia e marcacao de pontos de costa para confirmar posicao.', 'Determinar variacao magnetica.', 'Acionar leme sem piloto.'], correct: 'C', explanation: 'Distancias e marcacoes radar de pontas, ilhas e boias podem gerar linhas de posicao, especialmente a noite ou com visibilidade reduzida.', conceptKey: 'cpa2.eletronica.radar-posicao', difficulty: 'medium' },
  { id: 20253055, topic: 'navegacao eletronica / parallel indexing', statement: 'O parallel indexing no radar e usado para:', options: ['Calcular mare.', 'Monitorar se a embarcacao mantem distancia lateral segura de costa ou perigo.', 'Programar MMSI.', 'Aumentar estabilidade.', 'Substituir carta.'], correct: 'B', explanation: 'Uma linha paralela ao perigo ou contorno costeiro serve de referencia. Se o eco se aproxima da linha, a embarcacao pode estar saindo da margem planejada.', conceptKey: 'cpa2.eletronica.parallel-indexing', difficulty: 'hard' },
  { id: 20253056, topic: 'navegacao eletronica / arpa', statement: 'O ARPA ou rastreamento automatico de alvos deve ser entendido como:', options: ['Garantia de que nao havera colisao.', 'Substituto da vigia visual.', 'Auxilio para estimar movimento relativo, CPA e TCPA, sujeito a erros.', 'Sistema de estabilidade.', 'Comunicacao por satelite.'], correct: 'C', explanation: 'ARPA ajuda a analisar riscos, mas depende de eco bem adquirido, bom ajuste e tempo de estabilizacao. Manobras dos alvos podem invalidar previsoes antigas.', conceptKey: 'cpa2.eletronica.arpa', difficulty: 'hard' },
  { id: 20253057, topic: 'navegacao eletronica / ecobatimetro offset', statement: 'O ecobatimetro normalmente informa profundidade:', options: ['Sempre corrigida para o zero da carta.', 'Abaixo do transdutor, salvo se houver offset configurado.', 'Ate a proxima boia.', 'Da mare prevista no porto.', 'Lateral ate a costa.'], correct: 'B', explanation: 'Alguns equipamentos mostram profundidade sob o transdutor; outros usam offset para quilha ou linha d agua. Entender a configuracao evita erro de folga sob a quilha.', conceptKey: 'cpa2.eletronica.ecobatimetro-offset', difficulty: 'hard' },
  { id: 20253058, topic: 'navegacao eletronica / alarme de profundidade', statement: 'O alarme de profundidade deve ser regulado considerando:', options: ['Calado, offset, mare, ondas e margem minima.', 'Somente profundidade maxima da carta.', 'Canal VHF de emergencia.', 'Autonomia de agua doce.', 'Velocidade maxima do casco.'], correct: 'A', explanation: 'O alarme deve disparar antes de a folga ficar critica. Para isso, precisa refletir calado, sensor, nivel da agua e margem operacional desejada.', conceptKey: 'cpa2.eletronica.alarme-profundidade', difficulty: 'medium' },
  { id: 20253059, topic: 'navegacao eletronica / piloto automatico', statement: 'O uso de piloto automatico em navegacao costeira exige atencao porque:', options: ['Detecta automaticamente todo objeto flutuante.', 'Impede efeitos de corrente.', 'Dispensa planejamento.', 'Governa conforme comandos, mas nao substitui vigia nem avaliacao de trafego.', 'Garante distancia de perigos.'], correct: 'D', explanation: 'Piloto automatico reduz carga de governo, mas pode seguir rumo ou rota para uma situacao insegura se o comandante nao monitorar posicao, trafego, mar e alarmes.', conceptKey: 'cpa2.eletronica.piloto-automatico', difficulty: 'medium' },
  { id: 20253060, topic: 'navegacao eletronica / revisao de rota', statement: 'Antes de ativar uma rota no chartplotter, o comandante deve:', options: ['Confiar que o equipamento sempre cria rota segura.', 'Conferir cada perna quanto a perigos, profundidades, areas restritas e margem.', 'Apagar waypoints antigos sem revisar.', 'Ativar apenas dentro do canal.', 'Desligar alarmes.'], correct: 'B', explanation: 'Rotas automaticas ou antigas podem cruzar perigos ou areas restritas. A revisao humana e indispensavel antes de seguir qualquer rota.', conceptKey: 'cpa2.eletronica.revisao-rota', difficulty: 'hard' },
  { id: 20253061, topic: 'navegacao eletronica / carta atualizada', statement: 'Cartas eletronicas desatualizadas podem ser perigosas porque:', options: ['Podem omitir novas boias, areas restritas, perigos ou alteracoes de profundidade.', 'Impedem o motor de funcionar.', 'Eliminam a variacao magnetica.', 'Aumentam estabilidade.', 'Bloqueiam o ecobatimetro.'], correct: 'A', explanation: 'Cartas eletronicas tambem precisam de atualizacao. Mudancas de balizamento, obras, restricoes e informacoes de seguranca podem ser decisivas para a derrota.', conceptKey: 'cpa2.eletronica.carta-atualizada', difficulty: 'medium' },
  { id: 20253062, topic: 'navegacao eletronica / datum gps', statement: 'A configuracao de datum do GPS deve ser compatibilizada com:', options: ['Frequencia do canal 16.', 'Altura da antena VHF.', 'O datum da carta nautica ou eletronica usada.', 'Densidade da agua.', 'Centro de gravidade.'], correct: 'C', explanation: 'Coordenadas so coincidem corretamente quando usam o mesmo referencial geodesico. Datum incorreto desloca a posicao exibida em relacao aos perigos.', conceptKey: 'cpa2.eletronica.datum-gps', difficulty: 'hard' },
  { id: 20253063, topic: 'navegacao eletronica / mob', statement: 'A funcao MOB em GPS ou chartplotter deve ser acionada quando:', options: ['Pessoa cai ao mar, para marcar rapidamente a posicao do evento.', 'A embarcacao chega ao destino.', 'O motor e desligado.', 'Ha troca de carta.', 'O AIS recebe alvo distante.'], correct: 'A', explanation: 'MOB marca a posicao inicial da queda e auxilia o retorno. Como pessoa e embarcacao derivam, deve ser combinada com vigia e manobra imediata.', conceptKey: 'cpa2.eletronica.mob', difficulty: 'medium' },
  { id: 20253064, topic: 'navegação eletrônica / trilha gravada', statement: 'A trilha gravada no chartplotter deve ser usada com cautela porque:', options: ['Garante rota segura para sempre.', 'Substitui avisos aos navegantes.', 'Corrige a profundidade.', 'Repetir uma trilha antiga não garante maré, tráfego, balizamento e perigos iguais.', 'Impede falha de GPS.'], correct: 'D', explanation: 'Trilhas mostram por onde a embarcação passou antes, não por onde é seguro passar agora. Condições, restrições e dados náuticos podem mudar.', conceptKey: 'cpa2.eletronica.trilha-gravada', difficulty: 'medium' },
  { id: 20253065, topic: 'navegacao eletronica / redundancia', statement: 'Redundancia de meios de navegacao significa:', options: ['Usar varios aparelhos iguais na mesma fonte sem carta.', 'Ter formas independentes de confirmar posicao, rumo e profundidade.', 'Confiar apenas no celular.', 'Ignorar meios visuais.', 'Substituir planejamento por alarmes.'], correct: 'B', explanation: 'Redundancia real combina GPS, carta, bussola, ecobatimetro, radar, referencias visuais e energia de reserva. Assim, uma falha nao deixa a embarcacao sem orientacao.', conceptKey: 'cpa2.eletronica.redundancia', difficulty: 'medium' },
  { id: 20253066, topic: 'navegacao eletronica / energia a bordo', statement: 'A dependencia de instrumentos eletronicos torna essencial:', options: ['Desligar tudo em aguas restritas.', 'Usar apenas luz interna.', 'Gerenciar baterias, alimentacao e alternativas para equipamentos criticos.', 'Dispensar cartas.', 'Manter piloto automatico sempre ligado.'], correct: 'C', explanation: 'Sem energia, GPS, VHF, AIS, radar, luzes e bombas podem falhar. O comandante deve planejar consumo, carga, protecao eletrica e alternativas.', conceptKey: 'cpa2.eletronica.energia', difficulty: 'medium' },
  { id: 20253067, topic: 'navegacao eletronica / antena gps', statement: 'Uma antena GPS instalada em local inadequado pode causar:', options: ['Perda ou degradacao de sinal por sombreamento, interferencia ou reflexoes.', 'Precisao maxima garantida.', 'Correcao automatica de variacao.', 'Melhor estabilidade.', 'Reducao de calado.'], correct: 'A', explanation: 'Antenas GNSS precisam de boa visada do ceu e afastamento de interferencias. Instalacao ruim reduz satelites ou degrada a solucao de posicao.', conceptKey: 'cpa2.eletronica.antena-gps', difficulty: 'medium' },
  { id: 20253068, topic: 'navegacao eletronica / heading e cog', statement: 'A diferenca entre heading e COG e que:', options: ['Sao sempre iguais em corrente forte.', 'COG e medido por bussola parada.', 'Heading e profundidade.', 'Heading e a direcao da proa; COG e a direcao do movimento sobre o fundo.', 'COG e centro de gravidade.'], correct: 'D', explanation: 'Com vento ou corrente, a embarcacao pode apontar para uma direcao e deslocar-se em outra. Entender essa diferenca evita interpretacao errada da tela.', conceptKey: 'cpa2.eletronica.heading-cog', difficulty: 'medium' },
  { id: 20253069, topic: 'navegacao eletronica / overlay radar', statement: 'Em sobreposicao de radar na carta, desalinhamento persistente entre ecos e costa pode indicar:', options: ['Erro de heading, datum, calibracao, atraso de sensor ou posicionamento.', 'Mudanca fisica da costa.', 'Profundidade sempre falsa.', 'AIS em potencia baixa.', 'Falta de estabilidade.'], correct: 'A', explanation: 'Radar overlay depende de posicao, heading e calibracao. Se os ecos nao coincidem com a carta, a causa deve ser investigada antes de confiar na apresentacao.', conceptKey: 'cpa2.eletronica.overlay-radar', difficulty: 'hard' },
  { id: 20253070, topic: 'navegacao eletronica / zona de guarda', statement: 'Uma zona de guarda no radar e util para:', options: ['Medir altura das ondas.', 'Alertar quando um eco entra em area predefinida ao redor da embarcacao.', 'Corrigir carta eletronica.', 'Transmitir socorro.', 'Regular calado dinamico.'], correct: 'B', explanation: 'Guard zones ajudam a perceber alvos em aproximacao, especialmente com baixa visibilidade. Mesmo assim, dependem de ajuste correto e nao dispensam vigia.', conceptKey: 'cpa2.eletronica.zona-guarda', difficulty: 'medium' },
  { id: 20253071, topic: 'navegacao eletronica / filtro ais', statement: 'Filtrar alvos AIS por distancia ou categoria pode ser util, mas traz o risco de:', options: ['Ocultar informacoes relevantes se o filtro for inadequado.', 'Aumentar precisao de satelites.', 'Reduzir corrente de mare.', 'Apagar perigos da carta em papel.', 'Impedir luzes de navegacao.'], correct: 'A', explanation: 'Filtros reduzem excesso de dados, mas podem esconder alvos pequenos, lentos ou ainda distantes que se tornarao relevantes. Devem ser ajustados ao contexto.', conceptKey: 'cpa2.eletronica.filtro-ais', difficulty: 'medium' },
  { id: 20253072, topic: 'navegacao eletronica / rota automatica', statement: 'Uma rota sugerida automaticamente por aplicativo ou plotter deve ser aceita somente depois de:', options: ['Ver se a linha parece curta.', 'Conferir sinal de internet.', 'Aumentar zoom ate parecer livre.', 'Revisao nautica completa pelo comandante com criterios de seguranca.', 'Desativar alarmes.'], correct: 'D', explanation: 'Algoritmos podem errar por parametros, carta desatualizada, calado mal informado ou restricoes. A responsabilidade final pela rota e do comandante.', conceptKey: 'cpa2.eletronica.rota-automatica', difficulty: 'hard' },
  { id: 20253073, topic: 'navegacao eletronica / firmware', statement: 'Atualizacoes de software ou firmware em equipamentos de navegacao devem ser feitas com planejamento porque:', options: ['Sempre aumentam potencia do motor.', 'Podem alterar configuracoes, interfaces, cartas ou compatibilidade entre equipamentos.', 'Dispensam backup.', 'Devem ser feitas em canal estreito.', 'Eliminam treinamento.'], correct: 'B', explanation: 'Atualizacoes podem corrigir falhas, mas tambem mudar configuracoes. E prudente fazer backup de rotas e testar o sistema antes de navegacao critica.', conceptKey: 'cpa2.eletronica.firmware', difficulty: 'medium' },
  { id: 20253074, topic: 'navegacao eletronica / multipercurso gnss', statement: 'O erro de multipercurso em GNSS ocorre quando:', options: ['Sinais refletidos chegam ao receptor junto com o sinal direto.', 'O vento desloca a embarcacao.', 'A corrente altera SOG.', 'A antena VHF esta em canal errado.', 'O radar usa escala curta.'], correct: 'A', explanation: 'Reflexoes em estruturas, mastros, encostas ou edificios podem alterar o tempo aparente de chegada do sinal, degradando a posicao calculada.', conceptKey: 'cpa2.eletronica.multipercurso', difficulty: 'hard' },
  { id: 20253075, topic: 'navegacao eletronica / ebl vrm', statement: 'No radar, EBL e VRM sao usados para:', options: ['Regular volume VHF.', 'Configurar calado.', 'Medir marcacao e distancia de ecos.', 'Calcular mare automaticamente.', 'Escolher datum.'], correct: 'C', explanation: 'EBL e a linha eletronica de marcacao; VRM e o anel variavel de distancia. Juntos ajudam a acompanhar alvos e criar referencias de posicao.', conceptKey: 'cpa2.eletronica.ebl-vrm', difficulty: 'medium' },
  { id: 20253076, topic: 'navegacao eletronica / escala radar', statement: 'Ao se aproximar de um porto, a escala do radar deve ser ajustada para:', options: ['Ficar sempre na maior escala.', 'Ficar sempre na menor escala.', 'Eliminar necessidade de carta.', 'Mostrar detalhes proximos sem perder consciencia dos alvos importantes.', 'Fazer AIS detectar boias apagadas.'], correct: 'D', explanation: 'Escalas curtas mostram detalhes proximos; escalas longas mostram contexto. O operador deve alternar ou escolher a escala conforme o risco da fase da navegacao.', conceptKey: 'cpa2.eletronica.escala-radar', difficulty: 'medium' },
  { id: 20253077, topic: 'navegacao eletronica / bussola eletronica', statement: 'Uma bussola eletronica mal calibrada pode afetar:', options: ['Heading exibido, overlay de radar, piloto automatico e orientacao da carta.', 'Altura real da mare.', 'Volume de tanques.', 'Cor das boias.', 'Potencia do EPIRB.'], correct: 'A', explanation: 'Muitos sistemas dependem do heading. Se a bussola eletronica estiver errada, varias apresentacoes e automatismos podem ficar desalinhados.', conceptKey: 'cpa2.eletronica.bussola-eletronica', difficulty: 'hard' },
  { id: 20253078, topic: 'navegacao eletronica / rede nmea', statement: 'Falhas de integracao NMEA ou rede de bordo podem resultar em:', options: ['Melhor estabilidade.', 'Reducao de variacao magnetica.', 'Dados inconsistentes entre GPS, radar, AIS, piloto e displays.', 'Desaparecimento de perigos.', 'Melhor alcance VHF.'], correct: 'C', explanation: 'Equipamentos integrados compartilham posicao, heading, profundidade e alvos. Cabos, configuracoes ou mensagens erradas podem gerar informacao conflitante.', conceptKey: 'cpa2.eletronica.nmea', difficulty: 'hard' },
  { id: 20253079, topic: 'navegacao eletronica / celular como apoio', statement: 'Usar celular ou tablet como apoio de navegacao requer cautela porque:', options: ['E sempre mais preciso que GPS nautico.', 'Substitui cartas oficiais.', 'Mede profundidade sem sensor.', 'Elimina necessidade de VHF.', 'Pode falhar por bateria, agua, calor, sinal ou carta desatualizada.'], correct: 'E', explanation: 'Dispositivos moveis sao uteis como apoio, mas nao devem ser o unico meio critico. Energia, protecao, atualizacao e redundancia precisam ser considerados.', conceptKey: 'cpa2.eletronica.celular-apoio', difficulty: 'medium' },
  { id: 20253080, topic: 'navegacao eletronica / confianca excessiva', statement: 'Um dos maiores riscos da navegacao eletronica moderna e:', options: ['Confiar excessivamente em uma tela sem confirmar a situacao real por outros meios.', 'Aprender a usar carta nautica.', 'Ter alarmes configuraveis.', 'Ver velocidade sobre o fundo.', 'Usar energia eletrica.'], correct: 'A', explanation: 'Eletronica aumenta seguranca quando usada criticamente. O risco surge quando o comandante deixa de observar, conferir carta, avaliar trafego e planejar margens.', conceptKey: 'cpa2.eletronica.confianca-excessiva', difficulty: 'hard' },
  { id: 20253081, topic: 'estabilidade / peso alto', statement: 'Quando um peso consideravel e embarcado em ponto alto, o efeito mais provavel sobre a estabilidade inicial e:', options: ['Elevar o centro de gravidade e reduzir a altura metacentrica.', 'Baixar o centro de gravidade.', 'Nao alterar estabilidade.', 'Eliminar superficie livre.', 'Reduzir deslocamento.'], correct: 'A', explanation: 'Peso alto eleva G. Como a estabilidade inicial depende da relacao entre G e M, elevar G tende a reduzir GM e a margem de retorno apos inclinacao.', conceptKey: 'cpa2.estabilidade.peso-alto', difficulty: 'medium' },
  { id: 20253082, topic: 'estabilidade / peso baixo', statement: 'A colocacao de peso baixo e bem distribuido tende a:', options: ['Elevar o centro de gravidade.', 'Baixar o centro de gravidade e melhorar estabilidade inicial.', 'Eliminar lotacao maxima.', 'Aumentar superficie livre.', 'Reduzir a boca.'], correct: 'B', explanation: 'Peso baixo desloca G para baixo e tende a aumentar GM, desde que a embarcacao nao fique sobrecarregada e a distribuicao seja adequada.', conceptKey: 'cpa2.estabilidade.peso-baixo', difficulty: 'medium' },
  { id: 20253083, topic: 'estabilidade / superficie livre', statement: 'Tanques parcialmente cheios prejudicam a estabilidade porque:', options: ['Reduzem deslocamento a zero.', 'Eliminam momento de adricamento.', 'O l?quido se desloca para o bordo baixo e reduz a estabilidade efetiva.', 'Aumentam sempre borda livre.', 'Transformam GM negativo em positivo.'], correct: 'C', explanation: 'A superficie livre permite deslocamento lateral do l?quido quando a embarcacao aderna. Esse movimento cria efeito semelhante a elevar ou deslocar G, reduzindo estabilidade.', conceptKey: 'cpa2.estabilidade.superficie-livre', difficulty: 'medium' },
  { id: 20253084, topic: 'estabilidade / gm positivo', statement: 'Uma embarcacao com GM positivo, em pequenos angulos, tende a:', options: ['Aumentar inclinacao sem retorno.', 'Perder todo deslocamento.', 'Ficar sem calado de popa.', 'Gerar momento de adricamento e retornar a posicao de equilibrio.', 'Eliminar efeitos do vento.'], correct: 'D', explanation: 'GM positivo indica que o metacentro esta acima do centro de gravidade para pequenas inclinacoes, produzindo tendencia de retorno.', conceptKey: 'cpa2.estabilidade.gm-positivo', difficulty: 'medium' },
  { id: 20253085, topic: 'estabilidade / gm negativo', statement: 'Uma condicao de GM negativo e perigosa porque:', options: ['A embarcacao tende a aumentar a inclinacao em vez de voltar ao equilibrio.', 'Aumenta velocidade maxima.', 'Impede entrada de agua.', 'Diminui sempre o balanco de forma segura.', 'Elimina peso alto.'], correct: 'A', explanation: 'Com G acima de M, o momento inicial pode ser adernante. A embarcacao fica instavel e pode assumir banda acentuada ou emborcar.', conceptKey: 'cpa2.estabilidade.gm-negativo', difficulty: 'hard' },
  { id: 20253086, topic: 'estabilidade / banda permanente', statement: 'Uma banda permanente apos embarque de carga em um bordo indica possivelmente:', options: ['Aumento de profundidade local.', 'Distribuicao assimetrica de pesos e deslocamento lateral do centro de gravidade.', 'Trim longitudinal perfeito.', 'Ausencia de risco.', 'Falha obrigatoria do GPS.'], correct: 'B', explanation: 'Peso fora da linha de centro desloca G para o bordo carregado, criando momento adernante. A correcao exige redistribuicao e avaliacao da estabilidade.', conceptKey: 'cpa2.estabilidade.banda-permanente', difficulty: 'medium' },
  { id: 20253087, topic: 'estabilidade / trim', statement: 'Trim e a diferenca de calado entre:', options: ['Bombordo e boreste.', 'Linha d agua e conves.', 'Centro de carena e metacentro.', 'Proa e popa.', 'Tanque cheio e vazio.'], correct: 'D', explanation: 'Trim e a inclinacao longitudinal da embarcacao, percebida pela diferenca entre calado de vante e de re. Cargas na proa ou popa alteram esse equilibrio.', conceptKey: 'cpa2.estabilidade.trim', difficulty: 'medium' },
  { id: 20253088, topic: 'estabilidade / deslocamento transversal', statement: 'Ao deslocar um peso transversalmente para boreste, o centro de gravidade:', options: ['Desloca-se tambem para boreste, podendo gerar banda.', 'Desloca-se para bombordo.', 'Permanece imovel sempre.', 'Sobe apenas se o peso for l?quido.', 'Passa a coincidir com o metacentro.'], correct: 'A', explanation: 'O centro de gravidade acompanha o deslocamento dos pesos. Em embarcacoes pequenas, passageiros e cargas movidos para um bordo podem ter efeito grande.', conceptKey: 'cpa2.estabilidade.deslocamento-transversal', difficulty: 'medium' },
  { id: 20253089, topic: 'estabilidade / agua livre', statement: 'Agua livre no conves ou no interior e critica porque:', options: ['Sempre aumenta GM.', 'Nao altera deslocamento.', 'Elimina banda por vento.', 'Reduz calado.', 'Acrescenta peso movel e pode criar efeito de superficie livre.'], correct: 'E', explanation: 'Agua embarcada se desloca para o bordo baixo, acrescenta peso e reduz borda livre. A combinacao pode acelerar perda de estabilidade.', conceptKey: 'cpa2.estabilidade.agua-livre', difficulty: 'hard' },
  { id: 20253090, topic: 'estabilidade / borda livre', statement: 'A reducao excessiva da borda livre aumenta risco porque:', options: ['Facilita embarque de agua e reduz reserva de flutuabilidade.', 'Aumenta sempre GM.', 'Impede superficie livre.', 'Melhora resposta ao leme.', 'Diminui deslocamento.'], correct: 'A', explanation: 'Borda livre e a margem entre a linha d agua e pontos de entrada de agua. Quanto menor, maior a chance de alagamento e perda progressiva de estabilidade.', conceptKey: 'cpa2.estabilidade.borda-livre', difficulty: 'medium' },
  { id: 20253091, topic: 'estabilidade / carga maxima', statement: 'Ultrapassar a carga maxima recomendada compromete principalmente:', options: ['Apenas o conforto.', 'Somente o velocimetro.', 'Validade do GPS.', 'Borda livre, estabilidade, manobrabilidade e capacidade de recuperacao.', 'A cor das luzes.'], correct: 'D', explanation: 'Excesso de carga aumenta deslocamento, reduz borda livre e pode elevar ou deslocar G. Em emergencia, a margem de seguranca fica muito menor.', conceptKey: 'cpa2.estabilidade.carga-maxima', difficulty: 'medium' },
  { id: 20253092, topic: 'estabilidade / passageiros no bordo', statement: 'Em embarcacao pequena, passageiros se deslocando todos para o mesmo bordo podem:', options: ['Melhorar sempre a estabilidade.', 'Gerar banda perigosa por deslocamento lateral do centro de gravidade.', 'Reduzir ondas pela metade.', 'Aumentar profundidade.', 'Corrigir variacao magnetica.'], correct: 'B', explanation: 'Pessoas sao pesos moveis. Em embarcacoes pequenas, deslocamentos coletivos podem produzir momentos significativos e levar a adernacao ou embarque de agua.', conceptKey: 'cpa2.estabilidade.passageiros-bordo', difficulty: 'medium' },
  { id: 20253093, topic: 'estabilidade / mar de traves', statement: 'Uma embarcacao com estabilidade reduzida em mar de traves esta mais sujeita a:', options: ['Aumento garantido de velocidade.', 'Reducao de superficie livre.', 'Balancos amplos, embarque de agua e possivel emborcamento.', 'Eliminacao de banda.', 'Melhor leitura GPS.'], correct: 'C', explanation: 'Ondas pelo traves produzem momentos laterais. Com baixa estabilidade ou pouca borda livre, aumenta o risco de grandes adernacoes e alagamento.', conceptKey: 'cpa2.estabilidade.mar-traves', difficulty: 'hard' },
  { id: 20253094, topic: 'estabilidade / embarcacao dura', statement: 'Uma embarcacao excessivamente dura, com GM muito alto, tende a apresentar:', options: ['Balanco rapido e desconfortavel, com esforcos maiores.', 'Ausencia total de balanco.', 'GM negativo obrigatorio.', 'Calado zero.', 'Impossibilidade de governo.'], correct: 'A', explanation: 'GM alto aumenta o momento de retorno inicial, mas pode gerar balanco curto e violento. Estabilidade adequada nao significa simplesmente maximizar GM.', conceptKey: 'cpa2.estabilidade.embarcacao-dura', difficulty: 'hard' },
  { id: 20253095, topic: 'estabilidade / embarcacao branda', statement: 'Uma embarcacao branda, com GM pequeno, normalmente apresenta:', options: ['Seguranca absoluta.', 'Borda livre sempre maior.', 'Impossibilidade de banda.', 'Balanco lento e maior sensibilidade a pesos moveis e superficie livre.', 'Menor risco quando sobrecarregada.'], correct: 'D', explanation: 'GM pequeno reduz o momento inicial de adricamento. A embarcacao pode parecer confortavel, mas tem menor margem contra pesos altos, l?quidos livres e ondas laterais.', conceptKey: 'cpa2.estabilidade.embarcacao-branda', difficulty: 'hard' },
  { id: 20253096, topic: 'estabilidade / centro de carena', statement: 'O centro de carena corresponde:', options: ['Ao centro geometrico do volume de agua deslocado pela parte submersa.', 'Ao ponto onde todo peso se concentra.', 'Ao ponto da antena mais alta.', 'A intersecao entre rumo verdadeiro e magnetico.', 'Ao ponto medio da amarra.'], correct: 'A', explanation: 'O empuxo atua pelo centro de carena. Quando a embarcacao inclina, a forma submersa muda e esse centro se desloca, participando do braco de estabilidade.', conceptKey: 'cpa2.estabilidade.centro-carena', difficulty: 'medium' },
  { id: 20253097, topic: 'estabilidade / momento de adricamento', statement: 'O momento de adricamento e o efeito que:', options: ['Aumenta inclinacao em qualquer condicao.', 'Tende a trazer a embarcacao de volta a posicao direita apos inclinacao.', 'Elimina distribuicao de pesos.', 'Mede velocidade sobre o fundo.', 'Indica distancia ate waypoint.'], correct: 'B', explanation: 'Quando peso e empuxo formam um binario favoravel, surge momento de adricamento. Ele depende do deslocamento e do braco de estabilidade.', conceptKey: 'cpa2.estabilidade.momento-adricamento', difficulty: 'medium' },
  { id: 20253098, topic: 'estabilidade / carga na proa', statement: 'Carga excessiva concentrada na proa pode causar:', options: ['Banda permanente para boreste sempre.', 'Aumento de velocidade maxima.', 'Eliminacao de ondas de proa.', 'Desaparecimento de superficie livre.', 'Trim pela proa, menor borda livre avante e tendencia a embarcar agua.'], correct: 'E', explanation: 'Peso longitudinal altera trim. Proa baixa pode bater mais no mar, embarcar agua e prejudicar governo, reduzindo a margem de flutuabilidade avante.', conceptKey: 'cpa2.estabilidade.carga-proa', difficulty: 'medium' },
  { id: 20253099, topic: 'estabilidade / equipamento alto', statement: 'Instalar equipamento pesado em targa, flybridge ou teto sem avaliacao pode ser perigoso porque:', options: ['Eleva o centro de gravidade e reduz margem de estabilidade.', 'Reduz sempre o calado.', 'Impede banda por vento.', 'Aumenta volume estanque.', 'Corrige trim sempre.'], correct: 'A', explanation: 'Equipamentos altos podem ter grande efeito em G. Alteracoes estruturais ou instalacoes de peso elevado devem ser avaliadas antes de navegar.', conceptKey: 'cpa2.estabilidade.equipamento-alto', difficulty: 'hard' },
  { id: 20253100, topic: 'estabilidade / decisao operacional', statement: 'Ao perceber banda anormal, perda de borda livre e agua se deslocando a bordo, a prioridade e:', options: ['Manter derrota ate o destino.', 'Aumentar velocidade para planar.', 'Colocar passageiros no bordo baixo.', 'Desligar todos os equipamentos.', 'Controlar entrada de agua, redistribuir peso, reduzir risco e buscar abrigo ou socorro.'], correct: 'E', explanation: 'Esses sinais indicam perda de margem de estabilidade. A resposta deve reduzir momentos adernantes, remover agua livre, preservar governo e preparar alternativa segura.', conceptKey: 'cpa2.estabilidade.conduta-emergencia', difficulty: 'hard' },
]

